#include "../charge_compiler/json.hpp"
#include <algorithm>
#include <cstdint>
#include <fstream>
#include <iostream>
#include <unordered_map>
#include <unordered_set>
#include <time.h>
using I=long long;
static double now(){timespec t{};require(clock_gettime(CLOCK_BOOTTIME,&t)==0,"clock");return t.tv_sec+t.tv_nsec*1e-9;}
static void le(std::ostream& out,uint64_t n,int width){for(int k=0;k<width;k++)out.put(char(n>>(8*k)));}
struct Union{std::unordered_map<uint32_t,uint32_t> parent;uint32_t root(uint32_t i){auto it=parent.find(i);if(it==parent.end())return i;if(it->second!=i)it->second=root(it->second);return it->second;}bool join(uint32_t a,uint32_t b){parent.try_emplace(a,a);parent.try_emplace(b,b);a=root(a);b=root(b);if(a==b)return false;parent[std::max(a,b)]=std::min(a,b);return true;}};
int main(int argc,char**argv){try{
 require(argc==2,"usage: build_zero_R_voltage_map CONFIG");auto cfg=Json::read(argv[1]);I count=cfg.at("voltage_nodes").integer();require(count>1&&count<100000000,"bounded voltage namespace");double deadline=cfg.at("deadline_uptime").num();Union u;Json constraints=Json::array();std::unordered_set<std::string> identities;I total=0,positive=0,rank=0;
 std::ifstream input(cfg.at("branches").str());require(bool(input),"native R core branches");std::string line;while(std::getline(input,line)){if(total++%10000==0)require(now()<deadline,"zero-R constraint scan deadline");if(line.starts_with("{\"branch_kind\":\"positive_native_resistor\",")){positive++;continue;}auto row=Json::parse(line);require(row.at("branch_kind").str()=="exact_zero_voltage_constraint","typed native core branch");require(row.at("native_resistance_float_bits").integer()==0&&std::stold(row.at("native_resistance_milliohm_token").str())==0&&!row.obj().count("nominal_conductance_siemens"),"exact zero branch without finite conductance");I a=row.at("global_voltage_ids").at(0).integer(),b=row.at("global_voltage_ids").at(1).integer();require(a>0&&b>0&&a<count&&b<count,"zero-R native endpoints never reference/fallback");require(identities.insert(row.at("native_group_id").str()+":"+row.at("native_branch_pointer").str()).second,"unique native zero-R branch");rank+=u.join(a,b);constraints.push(row);}
 require(input.eof()&&total==cfg.at("expected_branches").integer()&&I(constraints.arr().size())==cfg.at("expected_zero_branches").integer(),"complete native core zero-R coverage");
 std::vector<uint32_t> removed;std::unordered_map<uint32_t,I> components;for(auto&[node,p]:u.parent){auto root=u.root(node);components[root]++;if(root!=node)removed.push_back(node);}std::sort(removed.begin(),removed.end());require(I(removed.size())==rank,"zero-R rank and removed state count");auto mapped=[&](uint32_t i){auto r=u.root(i);return uint32_t(r-std::distance(removed.begin(),std::lower_bound(removed.begin(),removed.end(),r)));};
 std::ofstream output(cfg.at("voltage_map").str(),std::ios::binary);require(bool(output),"zero-R voltage map output");output.write("CNETDOF1",8);le(output,count,8);le(output,count-rank,8);for(I i=0;i<count;i++){if(i%100000==0)require(now()<deadline,"zero-R map serialization deadline");le(output,mapped(i),4);}output.close();require(bool(output),"zero-R voltage map close");
 std::ofstream aliases(cfg.at("aliases").str());for(auto i:removed)aliases<<Json(Json::Array{I(i),I(u.root(i)),I(mapped(i))}).dump()<<'\n';aliases.close();require(bool(aliases),"zero-R alias ledger close");std::ofstream equations(cfg.at("constraints").str());for(auto row:constraints.arr()){auto a=row.at("global_voltage_ids").at(0).integer(),b=row.at("global_voltage_ids").at(1).integer();require(mapped(a)==mapped(b),"every native zero-R equation enforced");row["constrained_voltage_id"]=I(mapped(a));equations<<row.dump()<<'\n';}equations.close();require(bool(equations),"zero-R constraint ledger close");
 Json report=Json::object();report["original_voltage_nodes"]=count;report["constrained_voltage_nodes"]=count-rank;report["native_core_branches_scanned"]=total;report["positive_native_resistors_unchanged"]=positive;report["native_zero_voltage_equations"]=I(constraints.arr().size());report["independent_zero_voltage_equations"]=rank;report["redundant_zero_voltage_equations"]=I(constraints.arr().size())-rank;report["touched_voltage_nodes"]=I(u.parent.size());report["zero_R_connected_components"]=I(components.size());report["abstract_reference_preserved"]=mapped(0)==0;report["epsilon_resistance_added"]=false;report["substrate_reference_fold_applied"]=false;report["physical_RC_qualified"]=false;report["release_qualified"]=false;std::cout<<report.dump()<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
